        line = input()
        lines.append(line)
    except EOFError:
        break
    except KeyboardInterrupt:
        print()
        raise RuntimeError("用户取消了交互式输入")

change.new:
print("(输入完成后在新的一行输入 END 然后回车)", flush=True)
while True:
    try:
        line = input()
        if line.strip().upper() == "END":
            break
        lines.append(line)
    except KeyboardInterrupt:
        print()
        raise RuntimeError("用户取消了交互式输入")
